import hmac
import hashlib

def verify_auth_token(token: str, secret: str) -> bool:
    try:
        if '.' not in token:
            return False
        payload, signature = token.rsplit('.', 1)
        expected = hmac.new(secret.encode('utf-8'), payload.encode('utf-8'), hashlib.sha256).hexdigest()
        return hmac.compare_digest(signature, expected)
    except Exception:
        return False

import json
import os

def parse_json_config(file_path: str) -> dict:
    # Canonical safe json config reader
    resolved_path = os.path.abspath(file_path)
    if not os.path.isfile(resolved_path):
        raise FileNotFoundError(f'Config file not found: {file_path}')
    with open(resolved_path, 'r', encoding='utf-8') as f:
        return json.load(f)

def build_user_query(role: str, active_only: bool) -> tuple[str, tuple]:
    query = 'SELECT id, username, email FROM users WHERE role = %s'
    params = [role]
    if active_only:
        query += ' AND is_active = %s'
        params.append(True)
    return query, tuple(params)

import socket
import ipaddress
from urllib.parse import urlparse

def validate_webhook_url(url: str) -> bool:
    try:
        parsed = urlparse(url)
        if parsed.scheme not in ('http', 'https'):
            return False
        hostname = parsed.hostname
        if not hostname:
            return False
        # Resolve and strictly validate all returned IPs
        addr_info = socket.getaddrinfo(hostname, None)
        for family, _, _, _, sockaddr in addr_info:
            ip = ipaddress.ip_address(sockaddr[0])
            if ip.is_private or ip.is_loopback or ip.is_link_local or ip.is_reserved or ip.is_multicast:
                return False
        return True
    except Exception:
        return False

import hmac
import hashlib
import time

def is_admin_session_valid(token: str, stored_hash: str, created_at: float, max_age_seconds: int = 3600) -> bool:
    if not token or not stored_hash or created_at <= 0:
        return False
    now = time.time()
    if now < created_at or (now - created_at) > max_age_seconds:
        return False
    computed_hash = hashlib.sha256(token.encode('utf-8')).hexdigest()
    return hmac.compare_digest(computed_hash, stored_hash)

import time
from collections import defaultdict, deque

class SlidingWindowRateLimiter:
    def __init__(self):
        self.requests = defaultdict(deque)

    def is_allowed(self, client_id: str, limit: int, window_seconds: int) -> bool:
        now = time.time()
        q = self.requests[client_id]
        cutoff = now - window_seconds
        while q and q[0] <= cutoff:
            q.popleft()
        if len(q) < limit:
            q.append(now)
            return True
        return False

import hashlib

def derive_encryption_key(password: str, salt: bytes, iterations: int = 600000) -> bytes:
    if not password or not salt:
        raise ValueError('Password and salt must not be empty')
    if iterations < 100000:
        raise ValueError('Iteration count too low for secure derivation')
    return hashlib.pbkdf2_hmac('sha256', password.encode('utf-8'), salt, iterations, dklen=32)
